-- Writing guides for every prompt of the Writing practice tests: the text shown beside the prompt (question_versions.guide),
-- the six steps of the step-by-step mode (question_versions.guide_steps: theory, sentence frame, useful phrases and a
-- sample sentence per step) and, for each Task 1, the figure the prompt describes, drawn as an inline SVG data URI,
-- plus the chart facts (answer_spec.chartFacts) the grader checks a Task 1 essay against.
-- Idempotent: the guide and steps are overwritten and the chart assets use fixed ids.

ALTER TABLE question_versions ADD COLUMN IF NOT EXISTS guide_steps JSONB;

-- PT-WRITING-01 Task 1 (line graph)
INSERT INTO content_assets (id, asset_type, text_content, media_reference, duration_seconds, validation_status)
VALUES ('2e000000-0000-4000-8000-010000003001', 'IMAGE', 'Line graph: households owning mobile phones, computers, tablets and MP3 players, 1995-2015', 'data:image/svg+xml;base64,', NULL, 'VALID')
ON CONFLICT (id) DO UPDATE SET text_content = EXCLUDED.text_content, media_reference = EXCLUDED.media_reference;
INSERT INTO content_asset_links (id, asset_id, question_version_id, sort_order)
SELECT '2e000000-0000-4000-8000-020000003001', '2e000000-0000-4000-8000-010000003001', (SELECT sq.question_version_id FROM content_packages p
    JOIN content_package_versions v ON v.package_id = p.id
    JOIN content_sections s ON s.package_version_id = v.id
    JOIN section_questions sq ON sq.section_id = s.id
    WHERE p.code = 'PT-WRITING-01' AND s.part_no = 1 AND p.current_published_version_id = v.id LIMIT 1), 0
WHERE NOT EXISTS (SELECT 1 FROM content_asset_links WHERE id = '2e000000-0000-4000-8000-020000003001');
UPDATE question_versions SET guide = '## 1. Giải thích đề
Đề bài thuộc dạng **Line Graph**: yêu cầu mô tả sự thay đổi của các số liệu theo thời gian: tăng, giảm, dao động hay giữ ổn định.

## 2. Bố cục 4 đoạn
- **Introduction** (1-2 câu): paraphrase đề bài.
- **Overview** (2 câu): các đặc điểm nổi bật nhất, chưa đưa số liệu chi tiết.
- **Body 1** (3-4 câu): nhóm thông tin thứ nhất, kèm số liệu.
- **Body 2** (3-4 câu): nhóm thông tin còn lại, kèm số liệu và so sánh.

## 3. Lưu ý
- Dùng thì quá khứ đơn nếu mốc thời gian đã qua, thì tương lai nếu biểu đồ dự báo.
- Chọn 2 đặc điểm nổi bật nhất cho overview: xu hướng chung và đường cao nhất/thấp nhất.
- Nêu số liệu đầu, số liệu cuối và điểm đỉnh/đáy, không liệt kê từng mốc.
- Viết tối thiểu 150 từ trong khoảng 20 phút.', guide_steps = '[{"no":1,"section":"Introduction","title":"Paraphrase đề bài","instruction":"Viết lại đề bài bằng từ ngữ của bạn: chart nói về gì, ở đâu, khi nào.","theory":"Viết lại đề bài bằng từ đồng nghĩa, không chép nguyên văn; nêu loại biểu đồ, đối tượng và mốc thời gian.","structure":"The [chart type] [illustrates / shows / compares] [what] [where] [when].","vocabulary":[{"en":"illustrate","vi":"minh họa"},{"en":"compare","vi":"so sánh"},{"en":"give information about","vi":"cung cấp thông tin về"},{"en":"the proportion of","vi":"tỷ lệ của"},{"en":"over the period","vi":"trong suốt giai đoạn"},{"en":"between … and …","vi":"từ … đến …"}],"example":"The line graph illustrates the percentage of households that owned four types of electronic device between 1995 and 2015."},{"no":2,"section":"Overview","title":"Nhận xét chung","instruction":"Nêu 2 đặc điểm nổi bật nhất, chưa dùng số liệu chi tiết.","theory":"Overview nêu 2 xu hướng chính, không đưa số liệu chi tiết. Đặt ngay sau Introduction hoặc đầu Body 1.","structure":"Overall, [category A] [trend verb], while [category B] [contrasting trend verb].","vocabulary":[{"en":"rise steadily","vi":"tăng đều"},{"en":"climb to","vi":"leo lên mức"},{"en":"peak at","vi":"đạt đỉnh ở"},{"en":"fall sharply","vi":"giảm mạnh"},{"en":"fluctuate","vi":"dao động"},{"en":"remain stable","vi":"giữ ổn định"}],"example":"Overall, ownership of mobile phones and computers rose steadily, while tablets appeared only after 2010 and MP3 players declined after peaking."},{"no":3,"section":"Body 1","title":"Câu chủ đề","instruction":"Nêu ý chính của đoạn: nhóm thông tin nào được mô tả và nổi bật ra sao.","theory":"Nhóm các đường có xu hướng giống nhau vào cùng một đoạn thân bài và nêu ý chính của nhóm đó.","structure":"[Category A] and [category B] were the [most / least] [adjective] [items] by the end of the period.","vocabulary":[{"en":"rise steadily","vi":"tăng đều"},{"en":"climb to","vi":"leo lên mức"},{"en":"peak at","vi":"đạt đỉnh ở"},{"en":"fall sharply","vi":"giảm mạnh"},{"en":"fluctuate","vi":"dao động"},{"en":"remain stable","vi":"giữ ổn định"}],"example":"Mobile phones and computers were the two most widespread devices by the end of the period."},{"no":4,"section":"Body 1","title":"Mô tả số liệu","instruction":"Chọn số liệu tiêu biểu của nhóm thứ nhất và so sánh chúng.","theory":"Mô tả từng đường bằng số liệu đầu và cuối, kèm động từ chỉ xu hướng; so sánh bằng whereas / while.","structure":"[Category A] [verb] from [number] in [year] to [number] in [year], whereas [category B] [verb] from [number] to [number].","vocabulary":[{"en":"rise steadily","vi":"tăng đều"},{"en":"climb to","vi":"leo lên mức"},{"en":"peak at","vi":"đạt đỉnh ở"},{"en":"fall sharply","vi":"giảm mạnh"},{"en":"fluctuate","vi":"dao động"},{"en":"remain stable","vi":"giữ ổn định"}],"example":"Mobile phone ownership climbed from 5% in 1995 to 95% in 2015, whereas computers rose from 20% to 85%."},{"no":5,"section":"Body 2","title":"Câu chủ đề","instruction":"Chuyển sang nhóm còn lại và nêu ý chính của đoạn thứ hai.","theory":"Nhóm các đường có xu hướng giống nhau vào cùng một đoạn thân bài và nêu ý chính của nhóm đó.","structure":"[Category A] and [category B] were the [most / least] [adjective] [items] by the end of the period.","vocabulary":[{"en":"rise steadily","vi":"tăng đều"},{"en":"climb to","vi":"leo lên mức"},{"en":"peak at","vi":"đạt đỉnh ở"},{"en":"fall sharply","vi":"giảm mạnh"},{"en":"fluctuate","vi":"dao động"},{"en":"remain stable","vi":"giữ ổn định"}],"example":"The other two devices followed a very different pattern."},{"no":6,"section":"Body 2","title":"Mô tả số liệu","instruction":"Mô tả số liệu của nhóm còn lại và đối chiếu với đoạn trước.","theory":"Mô tả từng đường bằng số liệu đầu và cuối, kèm động từ chỉ xu hướng; so sánh bằng whereas / while.","structure":"[Category A] [verb] from [number] in [year] to [number] in [year], whereas [category B] [verb] from [number] to [number].","vocabulary":[{"en":"rise steadily","vi":"tăng đều"},{"en":"climb to","vi":"leo lên mức"},{"en":"peak at","vi":"đạt đỉnh ở"},{"en":"fall sharply","vi":"giảm mạnh"},{"en":"fluctuate","vi":"dao động"},{"en":"remain stable","vi":"giữ ổn định"}],"example":"Tablets were absent until 2010 and then reached 60% by 2015, while MP3 players peaked at 45% in 2010 before falling to 20%."}]'::jsonb,
    answer_spec = answer_spec || jsonb_build_object('chartFacts', 'Percentage of households owning electronic devices, 1995-2015. Mobile phone: 1995 5%, 2000 25%, 2005 60%, 2010 85%, 2015 95%. Computer: 1995 20%, 2000 35%, 2005 55%, 2010 75%, 2015 85%. Tablet: 1995 0%, 2000 0%, 2005 0%, 2010 15%, 2015 60%. MP3 player: 1995 5%, 2000 25%, 2005 40%, 2010 45%, 2015 20%.'::text)
WHERE id = (SELECT sq.question_version_id FROM content_packages p
    JOIN content_package_versions v ON v.package_id = p.id
    JOIN content_sections s ON s.package_version_id = v.id
    JOIN section_questions sq ON sq.section_id = s.id
    WHERE p.code = 'PT-WRITING-01' AND s.part_no = 1 AND p.current_published_version_id = v.id LIMIT 1);

