UPDATE question_versions SET guide = '## 1. Giải thích đề
Đề bài thuộc dạng **Bar Chart**: yêu cầu so sánh các nhóm hoặc các mốc thời gian bằng chiều cao của cột.

## 2. Bố cục 4 đoạn
- **Introduction** (1-2 câu): paraphrase đề bài.
- **Overview** (2 câu): các đặc điểm nổi bật nhất, chưa đưa số liệu chi tiết.
- **Body 1** (3-4 câu): nhóm thông tin thứ nhất, kèm số liệu.
- **Body 2** (3-4 câu): nhóm thông tin còn lại, kèm số liệu và so sánh.

## 3. Lưu ý
- So sánh bằng cấp so sánh hơn và cấp cao nhất: the highest, slightly lower than, twice as high as.
- Overview nêu nhóm cao nhất và thấp nhất, hoặc xu hướng chung giữa hai mốc.
- Nhóm các cột có giá trị gần nhau vào cùng một đoạn.
- Viết tối thiểu 150 từ trong khoảng 20 phút.', guide_steps = '[{"no":1,"section":"Introduction","title":"Paraphrase đề bài","instruction":"Viết lại đề bài bằng từ ngữ của bạn: chart nói về gì, ở đâu, khi nào.","theory":"Viết lại đề bài bằng từ đồng nghĩa, không chép nguyên văn; nêu loại biểu đồ, đối tượng và mốc thời gian.","structure":"The [chart type] [illustrates / shows / compares] [what] [where] [when].","vocabulary":[{"en":"illustrate","vi":"minh họa"},{"en":"compare","vi":"so sánh"},{"en":"give information about","vi":"cung cấp thông tin về"},{"en":"the proportion of","vi":"tỷ lệ của"},{"en":"over the period","vi":"trong suốt giai đoạn"},{"en":"between … and …","vi":"từ … đến …"}],"example":"The bar chart compares the average number of hours that students in five countries spent studying each week in 2020."},{"no":2,"section":"Overview","title":"Nhận xét chung","instruction":"Nêu 2 đặc điểm nổi bật nhất, chưa dùng số liệu chi tiết.","theory":"Overview chỉ ra nhóm nổi bật nhất và nhóm thấp nhất, không liệt kê số liệu.","structure":"Overall, [category A] had the [highest] figure, whereas [category B] recorded the [lowest].","vocabulary":[{"en":"account for","vi":"chiếm"},{"en":"the highest figure","vi":"con số cao nhất"},{"en":"followed by","vi":"tiếp theo là"},{"en":"compared with","vi":"so với"},{"en":"slightly lower than","vi":"thấp hơn một chút so với"},{"en":"twice as high as","vi":"cao gấp đôi"}],"example":"Overall, students in Korea studied the longest, whereas those in Brazil studied the least."},{"no":3,"section":"Body 1","title":"Câu chủ đề","instruction":"Nêu ý chính của đoạn: nhóm thông tin nào được mô tả và nổi bật ra sao.","theory":"Mỗi thân bài gom các nhóm có mức tương đương nhau và nêu nhận xét chung về nhóm đó.","structure":"[Category A] and [category B] recorded the [highest / lowest] figures.","vocabulary":[{"en":"account for","vi":"chiếm"},{"en":"the highest figure","vi":"con số cao nhất"},{"en":"followed by","vi":"tiếp theo là"},{"en":"compared with","vi":"so với"},{"en":"slightly lower than","vi":"thấp hơn một chút so với"},{"en":"twice as high as","vi":"cao gấp đôi"}],"example":"Korea and Japan recorded the highest figures."},{"no":4,"section":"Body 1","title":"Mô tả số liệu","instruction":"Chọn số liệu tiêu biểu của nhóm thứ nhất và so sánh chúng.","theory":"Nêu số liệu cụ thể theo thứ tự từ cao xuống thấp, dùng followed by, compared with, while.","structure":"[Category A] stood at [number], followed by [category B] with [number], while [category C] was the lowest at [number].","vocabulary":[{"en":"account for","vi":"chiếm"},{"en":"the highest figure","vi":"con số cao nhất"},{"en":"followed by","vi":"tiếp theo là"},{"en":"compared with","vi":"so với"},{"en":"slightly lower than","vi":"thấp hơn một chút so với"},{"en":"twice as high as","vi":"cao gấp đôi"}],"example":"Korean students studied for 18 hours a week, followed by Japanese students with 14 hours."},{"no":5,"section":"Body 2","title":"Câu chủ đề","instruction":"Chuyển sang nhóm còn lại và nêu ý chính của đoạn thứ hai.","theory":"Mỗi thân bài gom các nhóm có mức tương đương nhau và nêu nhận xét chung về nhóm đó.","structure":"[Category A] and [category B] recorded the [highest / lowest] figures.","vocabulary":[{"en":"account for","vi":"chiếm"},{"en":"the highest figure","vi":"con số cao nhất"},{"en":"followed by","vi":"tiếp theo là"},{"en":"compared with","vi":"so với"},{"en":"slightly lower than","vi":"thấp hơn một chút so với"},{"en":"twice as high as","vi":"cao gấp đôi"}],"example":"The remaining three countries were noticeably lower."},{"no":6,"section":"Body 2","title":"Mô tả số liệu","instruction":"Mô tả số liệu của nhóm còn lại và đối chiếu với đoạn trước.","theory":"Nêu số liệu cụ thể theo thứ tự từ cao xuống thấp, dùng followed by, compared with, while.","structure":"[Category A] stood at [number], followed by [category B] with [number], while [category C] was the lowest at [number].","vocabulary":[{"en":"account for","vi":"chiếm"},{"en":"the highest figure","vi":"con số cao nhất"},{"en":"followed by","vi":"tiếp theo là"},{"en":"compared with","vi":"so với"},{"en":"slightly lower than","vi":"thấp hơn một chút so với"},{"en":"twice as high as","vi":"cao gấp đôi"}],"example":"Canada had 12 hours and Germany 11, while Brazil had the lowest figure at just 9 hours."}]'::jsonb,
    answer_spec = answer_spec || jsonb_build_object('chartFacts', 'Average weekly study time of students, 2020. Hours: Japan 14 hours, Korea 18 hours, Germany 11 hours, Brazil 9 hours, Canada 12 hours.'::text)
WHERE id = (SELECT sq.question_version_id FROM content_packages p
    JOIN content_package_versions v ON v.package_id = p.id
    JOIN content_sections s ON s.package_version_id = v.id
    JOIN section_questions sq ON sq.section_id = s.id
    WHERE p.code = 'PT-WRITING-02' AND s.part_no = 1 AND p.current_published_version_id = v.id LIMIT 1);

