UPDATE question_versions SET guide = '## 1. Giải thích đề
Đề bài thuộc dạng **Process**: yêu cầu mô tả các giai đoạn của một quy trình theo đúng thứ tự.

## 2. Bố cục 4 đoạn
- **Introduction** (1-2 câu): paraphrase đề bài.
- **Overview** (2 câu): các đặc điểm nổi bật nhất, chưa đưa số liệu chi tiết.
- **Body 1** (3-4 câu): nhóm thông tin thứ nhất, kèm số liệu.
- **Body 2** (3-4 câu): nhóm thông tin còn lại, kèm số liệu và so sánh.

## 3. Lưu ý
- Dùng thể bị động ở thì hiện tại đơn: the leaves are picked, the pulp is dried.
- Overview nêu số giai đoạn, điểm bắt đầu và điểm kết thúc.
- Nối các giai đoạn bằng first, then, after that, finally.
- Viết tối thiểu 150 từ trong khoảng 20 phút.', guide_steps = '[{"no":1,"section":"Introduction","title":"Paraphrase đề bài","instruction":"Viết lại đề bài bằng từ ngữ của bạn: chart nói về gì, ở đâu, khi nào.","theory":"Viết lại đề bài bằng từ đồng nghĩa, không chép nguyên văn; nêu loại biểu đồ, đối tượng và mốc thời gian.","structure":"The [chart type] [illustrates / shows / compares] [what] [where] [when].","vocabulary":[{"en":"illustrate","vi":"minh họa"},{"en":"compare","vi":"so sánh"},{"en":"give information about","vi":"cung cấp thông tin về"},{"en":"the proportion of","vi":"tỷ lệ của"},{"en":"over the period","vi":"trong suốt giai đoạn"},{"en":"between … and …","vi":"từ … đến …"}],"example":"The diagram illustrates the stages in the production of tea bags, from picking the leaves to boxing the finished product."},{"no":2,"section":"Overview","title":"Nhận xét chung","instruction":"Nêu 2 đặc điểm nổi bật nhất, chưa dùng số liệu chi tiết.","theory":"Overview nêu tổng số giai đoạn, giai đoạn đầu và giai đoạn cuối, không mô tả chi tiết.","structure":"Overall, the process has [number] stages, beginning with [first stage] and ending with [last stage].","vocabulary":[{"en":"is collected","vi":"được thu gom"},{"en":"is passed through","vi":"được cho qua"},{"en":"is pressed into","vi":"được ép thành"},{"en":"is dried","vi":"được làm khô"},{"en":"subsequently","vi":"sau đó"},{"en":"finally","vi":"cuối cùng"}],"example":"Overall, the process has seven stages, beginning with the picking of tea leaves and ending with the packaging of tea bags into boxes."},{"no":3,"section":"Body 1","title":"Câu chủ đề","instruction":"Nêu ý chính của đoạn: nhóm thông tin nào được mô tả và nổi bật ra sao.","theory":"Chia quy trình làm hai phần hợp lý, ví dụ giai đoạn chuẩn bị và giai đoạn hoàn thiện, rồi nêu ý chính mỗi phần.","structure":"The [first / last] [number] stages [prepare / turn] [the material] [into the product].","vocabulary":[{"en":"is collected","vi":"được thu gom"},{"en":"is passed through","vi":"được cho qua"},{"en":"is pressed into","vi":"được ép thành"},{"en":"is dried","vi":"được làm khô"},{"en":"subsequently","vi":"sau đó"},{"en":"finally","vi":"cuối cùng"}],"example":"The first four stages prepare the leaves."},{"no":4,"section":"Body 1","title":"Mô tả số liệu","instruction":"Chọn số liệu tiêu biểu của nhóm thứ nhất và so sánh chúng.","theory":"Mô tả tuần tự từng giai đoạn bằng câu bị động và từ nối trình tự.","structure":"First, [material] is [verb-ed], and then it is [verb-ed], after which it is [verb-ed].","vocabulary":[{"en":"is collected","vi":"được thu gom"},{"en":"is passed through","vi":"được cho qua"},{"en":"is pressed into","vi":"được ép thành"},{"en":"is dried","vi":"được làm khô"},{"en":"subsequently","vi":"sau đó"},{"en":"finally","vi":"cuối cùng"}],"example":"First, the leaves are picked and then withered, after which they are rolled and finally dried."},{"no":5,"section":"Body 2","title":"Câu chủ đề","instruction":"Chuyển sang nhóm còn lại và nêu ý chính của đoạn thứ hai.","theory":"Chia quy trình làm hai phần hợp lý, ví dụ giai đoạn chuẩn bị và giai đoạn hoàn thiện, rồi nêu ý chính mỗi phần.","structure":"The [first / last] [number] stages [prepare / turn] [the material] [into the product].","vocabulary":[{"en":"is collected","vi":"được thu gom"},{"en":"is passed through","vi":"được cho qua"},{"en":"is pressed into","vi":"được ép thành"},{"en":"is dried","vi":"được làm khô"},{"en":"subsequently","vi":"sau đó"},{"en":"finally","vi":"cuối cùng"}],"example":"The last three stages turn the dried leaves into a finished product."},{"no":6,"section":"Body 2","title":"Mô tả số liệu","instruction":"Mô tả số liệu của nhóm còn lại và đối chiếu với đoạn trước.","theory":"Mô tả tuần tự từng giai đoạn bằng câu bị động và từ nối trình tự.","structure":"First, [material] is [verb-ed], and then it is [verb-ed], after which it is [verb-ed].","vocabulary":[{"en":"is collected","vi":"được thu gom"},{"en":"is passed through","vi":"được cho qua"},{"en":"is pressed into","vi":"được ép thành"},{"en":"is dried","vi":"được làm khô"},{"en":"subsequently","vi":"sau đó"},{"en":"finally","vi":"cuối cùng"}],"example":"The dried leaves are sorted by size, packed into paper bags and, in the final stage, placed in boxes."}]'::jsonb,
    answer_spec = answer_spec || jsonb_build_object('chartFacts', 'How tea bags are made. Stages in order: 1) Leaves are picked; 2) Leaves are withered; 3) Leaves are rolled; 4) Leaves are dried; 5) Sorted by size; 6) Packed into paper bags; 7) Bags are boxed.'::text)
WHERE id = (SELECT sq.question_version_id FROM content_packages p
    JOIN content_package_versions v ON v.package_id = p.id
    JOIN content_sections s ON s.package_version_id = v.id
    JOIN section_questions sq ON sq.section_id = s.id
    WHERE p.code = 'PT-WRITING-05' AND s.part_no = 1 AND p.current_published_version_id = v.id LIMIT 1);

