c xây cạnh"},{"en":"to the north of","vi":"ở phía bắc của"},{"en":"was demolished","vi":"bị phá bỏ"},{"en":"was extended","vi":"được mở rộng"}],"example":"The most striking changes took place on the edge of the village."},{"no":4,"section":"Body 1","title":"Mô tả số liệu","instruction":"Chọn số liệu tiêu biểu của nhóm thứ nhất và so sánh chúng.","theory":"Mô tả từng thay đổi bằng thể bị động và giới từ chỉ vị trí.","structure":"[Old feature] was [replaced by / converted into] [new feature], and a new [feature] was built [beside / to the north of] [place].","vocabulary":[{"en":"was replaced by","vi":"được thay bằng"},{"en":"was converted into","vi":"được chuyển thành"},{"en":"was built beside","vi":"được xây cạnh"},{"en":"to the north of","vi":"ở phía bắc của"},{"en":"was demolished","vi":"bị phá bỏ"},{"en":"was extended","vi":"được mở rộng"}],"example":"Farmland was replaced by housing, and the pond was filled in."},{"no":5,"section":"Body 2","title":"Câu chủ đề","instruction":"Chuyển sang nhóm còn lại và nêu ý chính của đoạn thứ hai.","theory":"Gom các thay đổi theo khu vực địa lý hoặc theo loại công trình để mỗi đoạn có một chủ đề.","structure":"The most striking changes took place in [the east / the centre / on the coast].","vocabulary":[{"en":"was replaced by","vi":"được thay bằng"},{"en":"was converted into","vi":"được chuyển thành"},{"en":"was built beside","vi":"được xây cạnh"},{"en":"to the north of","vi":"ở phía bắc của"},{"en":"was demolished","vi":"bị phá bỏ"},{"en":"was extended","vi":"được mở rộng"}],"example":"Changes also affected the buildings in the centre."},{"no":6,"section":"Body 2","title":"Mô tả số liệu","instruction":"Mô tả số liệu của nhóm còn lại và đối chiếu với đoạn trước.","theory":"Mô tả từng thay đổi bằng thể bị động và giới từ chỉ vị trí.","structure":"[Old feature] was [replaced by / converted into] [new feature], and a new [feature] was built [beside / to the north of] [place].","vocabulary":[{"en":"was replaced by","vi":"được thay bằng"},{"en":"was converted into","vi":"được chuyển thành"},{"en":"was built beside","vi":"được xây cạnh"},{"en":"to the north of","vi":"ở phía bắc của"},{"en":"was demolished","vi":"bị phá bỏ"},{"en":"was extended","vi":"được mở rộng"}],"example":"The old school became a library, and a new car park was built beside the station."}]'::jsonb,
