UPDATE question_versions SET guide = '## 1. Giải thích đề
Đề bài thuộc dạng **Table**: yêu cầu chọn lọc và so sánh các số liệu nổi bật trong bảng, không chép lại toàn bộ.

## 2. Bố cục 4 đoạn
- **Introduction** (1-2 câu): paraphrase đề bài.
- **Overview** (2 câu): các đặc điểm nổi bật nhất, chưa đưa số liệu chi tiết.
- **Body 1** (3-4 câu): nhóm thông tin thứ nhất, kèm số liệu.
- **Body 2** (3-4 câu): nhóm thông tin còn lại, kèm số liệu và so sánh.

## 3. Lưu ý
- Tìm số liệu cao nhất, thấp nhất và các thay đổi lớn nhất theo hàng hoặc cột.
- Overview nêu xu hướng chung và nhóm nổi bật nhất.
- Gom các hàng có xu hướng giống nhau vào cùng một đoạn.
- Viết tối thiểu 150 từ trong khoảng 20 phút.', guide_steps = '[{"no":1,"section":"Introduction","title":"Paraphrase đề bài","instruction":"Viết lại đề bài bằng từ ngữ của bạn: chart nói về gì, ở đâu, khi nào.","theory":"Viết lại đề bài bằng từ đồng nghĩa, không chép nguyên văn; nêu loại biểu đồ, đối tượng và mốc thời gian.","structure":"The [chart type] [illustrates / shows / compares] [what] [where] [when].","vocabulary":[{"en":"illustrate","vi":"minh họa"},{"en":"compare","vi":"so sánh"},{"en":"give information about","vi":"cung cấp thông tin về"},{"en":"the proportion of","vi":"tỷ lệ của"},{"en":"over the period","vi":"trong suốt giai đoạn"},{"en":"between … and …","vi":"từ … đến …"}],"example":"The table compares the average number of visits each person made to public libraries in one year, by age group, in 2000 and 2020."},{"no":2,"section":"Overview","title":"Nhận xét chung","instruction":"Nêu 2 đặc điểm nổi bật nhất, chưa dùng số liệu chi tiết.","theory":"Overview chỉ nêu xu hướng chung và hàng/cột nổi bật, không đưa số liệu.","structure":"Overall, [group A] had the highest figures, whereas [group B] showed the biggest [rise / fall].","vocabulary":[{"en":"the highest proportion","vi":"tỷ lệ cao nhất"},{"en":"edge up","vi":"nhích lên"},{"en":"slip from … to …","vi":"giảm nhẹ từ … xuống …"},{"en":"remain steady","vi":"giữ ổn định"},{"en":"by contrast","vi":"ngược lại"},{"en":"respectively","vi":"lần lượt"}],"example":"Overall, library use fell in most age groups, with the over-65s the only group to visit more often."},{"no":3,"section":"Body 1","title":"Câu chủ đề","instruction":"Nêu ý chính của đoạn: nhóm thông tin nào được mô tả và nổi bật ra sao.","theory":"Mỗi thân bài gom các nhóm có xu hướng giống nhau và nêu nhận xét chung.","structure":"The [two youngest / oldest] groups were the [most / least] [adjective] but followed different paths.","vocabulary":[{"en":"the highest proportion","vi":"tỷ lệ cao nhất"},{"en":"edge up","vi":"nhích lên"},{"en":"slip from … to …","vi":"giảm nhẹ từ … xuống …"},{"en":"remain steady","vi":"giữ ổn định"},{"en":"by contrast","vi":"ngược lại"},{"en":"respectively","vi":"lần lượt"}],"example":"Visits by children and young adults dropped."},{"no":4,"section":"Body 1","title":"Mô tả số liệu","instruction":"Chọn số liệu tiêu biểu của nhóm thứ nhất và so sánh chúng.","theory":"Nêu số liệu chọn lọc của từng nhóm, so sánh bằng while / whereas / by contrast.","structure":"Among [group A], the figure [verb] from [x] to [y], while [group B] stayed between [x] and [y].","vocabulary":[{"en":"the highest proportion","vi":"tỷ lệ cao nhất"},{"en":"edge up","vi":"nhích lên"},{"en":"slip from … to …","vi":"giảm nhẹ từ … xuống …"},{"en":"remain steady","vi":"giữ ổn định"},{"en":"by contrast","vi":"ngược lại"},{"en":"respectively","vi":"lần lượt"}],"example":"Under-16s went from 9 visits to 6, and the 16 to 24 group fell from 4 to 3."},{"no":5,"section":"Body 2","title":"Câu chủ đề","instruction":"Chuyển sang nhóm còn lại và nêu ý chính của đoạn thứ hai.","theory":"Mỗi thân bài gom các nhóm có xu hướng giống nhau và nêu nhận xét chung.","structure":"The [two youngest / oldest] groups were the [most / least] [adjective] but followed different paths.","vocabulary":[{"en":"the highest proportion","vi":"tỷ lệ cao nhất"},{"en":"edge up","vi":"nhích lên"},{"en":"slip from … to …","vi":"giảm nhẹ từ … xuống …"},{"en":"remain steady","vi":"giữ ổn định"},{"en":"by contrast","vi":"ngược lại"},{"en":"respectively","vi":"lần lượt"}],"example":"The picture for older people was more varied."},{"no":6,"section":"Body 2","title":"Mô tả số liệu","instruction":"Mô tả số liệu của nhóm còn lại và đối chiếu với đoạn trước.","theory":"Nêu số liệu chọn lọc của từng nhóm, so sánh bằng while / whereas / by contrast.","structure":"Among [group A], the figure [verb] from [x] to [y], while [group B] stayed between [x] and [y].","vocabulary":[{"en":"the highest proportion","vi":"tỷ lệ cao nhất"},{"en":"edge up","vi":"nhích lên"},{"en":"slip from … to …","vi":"giảm nhẹ từ … xuống …"},{"en":"remain steady","vi":"giữ ổn định"},{"en":"by contrast","vi":"ngược lại"},{"en":"respectively","vi":"lần lượt"}],"example":"Visits by 25 to 44-year-olds slipped from 5 to 4 and by 45 to 64-year-olds from 7 to 5, whereas the 65-and-over group rose from 11 to 12."}]'::jsonb,
    answer_spec = answer_spec || jsonb_build_object('chartFacts', 'Average library visits per person per year. Under 16: 2000 9, 2020 6. 16 to 24: 2000 4, 2020 3. 25 to 44: 2000 5, 2020 4. 45 to 64: 2000 7, 2020 5. 65 and over: 2000 11, 2020 12.'::text)
